// Abort BEFORE burning a partial episode — an episode renders every scene (💸).
// Mirrors MIN_TOKEN_BALANCE=2000 in show/LuckyDay/show.env.
// Doubles as the config preflight, so an unfilled Show config fails here in
// seconds — not after the story step.
const cfg = $('Show config').first().json;
if (!cfg.campaignId) throw new Error('Show config: campaignId is empty — set it to a campaign id the API credential\'s account owns');
if (!cfg.userId) throw new Error('Show config: userId is empty — set it to the YakYak user id the API credential belongs to');
const user = $json;
if (user.tokenBalance === undefined) throw new Error('could not fetch the user record — check Show config userId and the "YakYak API" credential (' + (user.error?.message || 'no tokenBalance in response') + ')');
const balance = Number(user.tokenBalance || 0);
const min = Number(cfg.minTokenBalance || 2000);
if (balance < min) throw new Error('token balance ' + balance + ' is below the ' + min + ' minimum — top up before generating an episode');
return [{ json: { balance } }];

// Deterministic daily story — JS port of show/LuckyDay/compute.py, replacing
// the whole prompt/model stage: no Claude call, no Anthropic credential, no
// network. Same 14-scene structure: Mandarin Dialog lines (subtitled in brush
// calligraphy), English prose (it feeds the image prompts), no trailing period.
// The day's stem/branch/element use the SAME proleptic-Gregorian ordinal as
// compute.py (so they match a showrunner run); word-bank picks are keyed by
// FNV-1a instead of Python's sha256, so the WORDING differs — but it is equally
// deterministic (same date in -> same story out). Same almanac caveat as the
// original: the cycle is correct, the absolute phase is not anchored to a real
// Tong Shu epoch.
const MASTER = 'The Feng Shui Master';
// (cast name [EN, matches the alias map], 汉字, 地支 branch) in Earthly-Branch order
const ANIMALS = [
  ['Rat', '鼠', '子'],
  ['Ox', '牛', '丑'],
  ['Tiger', '虎', '寅'],
  ['Rabbit', '兔', '卯'],
  ['Dragon', '龙', '辰'],
  ['Snake', '蛇', '巳'],
  ['Horse', '马', '午'],
  ['Goat', '羊', '未'],
  ['Monkey', '猴', '申'],
  ['Rooster', '鸡', '酉'],
  ['Dog', '狗', '戌'],
  ['Pig', '猪', '亥'],
];
const STEMS = ['甲', '乙', '丙', '丁', '戊', '己', '庚', '辛', '壬', '癸'];
const ELEMENTS = [['金', 'Metal'], ['木', 'Wood'], ['水', 'Water'], ['火', 'Fire'], ['土', 'Earth']];
const YI = ['宜守成', '宜求财', '宜会友', '宜养气', '宜进取', '宜行善', '宜整理', '宜早眠'];
const JI = ['忌冲动', '忌轻信', '忌远行', '忌动土', '忌借贷', '忌口舌', '忌贪进', '忌熬夜'];
const DIRECTIONS = ['东', '南', '西', '北', '东南', '西南', '东北', '西北'];
const DIR_EN = { '东': 'east', '南': 'south', '西': 'west', '北': 'north', '东南': 'southeast', '西南': 'southwest', '东北': 'northeast', '西北': 'northwest' };
const PACE = ['缓行', '三思', '从容', '谨慎'];
const GENERAL_YI = ['宜安神养气', '宜清心寡欲', '宜广结善缘', '宜守正持中', '宜居家静处', '宜布施积福'];
const BLESSINGS = [
  '愿诸位顺遂安康，明日再会',
  '心安即是福，明日再聚',
  '守正得福，来日方长',
  '愿君财源广进，诸事如意',
  '静以养德，福自天来',
  '今日已言，吉凶在心',
];
const SETTINGS = [
  'a moon-gate courtyard where incense smoke curls',
  'a tea house balcony above a misted river',
  'a stone garden raked into slow spirals',
  'a red-lacquer hall hung with gold lanterns',
  'a bamboo grove bending in a quiet wind',
  'a temple threshold where koi circle a still pond',
  'a mountain shrine wrapped in dawn cloud',
  "a scholar's study stacked with bound scrolls",
];

function h32(s) { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); } return h >>> 0; }
const pickB = (bank, ...keys) => bank[h32(keys.join('|')) % bank.length];

const now = new Date();
const days = Math.floor(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()) / 86400000);
const n = days + 719163; // Python date.toordinal() parity (1970-01-01 -> 719163)
const iso = now.toISOString().slice(0, 10);
const ts = now.toISOString();

const stem = STEMS[n % 10];
const branchIdx = n % 12;
const elemCn = ELEMENTS[n % 5][0], elemEn = ELEMENTS[n % 5][1];
const ruling = ANIMALS[branchIdx];            // the day's ruling animal (地支 of the day)
const clash = ANIMALS[(branchIdx + 6) % 12];  // the 冲 (clash) animal — caution today
const goodDir = pickB(DIRECTIONS, n, 'good-dir');
const badDir = pickB(DIRECTIONS.filter((x) => x !== goodDir), n, 'bad-dir');

const out = [];
out.push('# Lucky Day — Daily Feng Shui Almanac');
out.push('**Generated (UTC):** ' + ts);
out.push('**For:** ' + iso + ' · 干支 ' + stem + ruling[2] + ' · ' + elemCn + '(' + elemEn + ') day');
out.push('');
out.push('## Headlines we drew from:');
const capBullet = '今日运势 Daily Feng Shui Almanac — a ' + elemEn + ' day ruled by the ' + ruling[0] + ' (' + ruling[1] + '); luck favors the ' + DIR_EN[goodDir] + ', caution for the ' + clash[0] + '. Find your sign 🧧';
out.push('- ' + capBullet);
for (const [name, cn] of ANIMALS) out.push('- ' + name + ' (' + cn + '): ' + pickB(YI, n, name, 'yi'));
out.push('');

const generalYi = pickB(GENERAL_YI, n, 'general-yi');
const pace = pickB(PACE, n, 'pace');
out.push('## Scene 1 — The Feng Shui Master opens the day');
out.push('**Leading character:** ' + MASTER);
out.push('**Dialog:** "今日' + stem + ruling[2] + elemCn + '日，' + generalYi + '，诸事' + pace + '；吉方在' + goodDir + '，凶方在' + badDir + '"');
out.push('');
out.push('Interior of ' + pickB(SETTINGS, n, 'master-intro') + ', rendered as a traditional Chinese ink-wash (国画) painting — gold leaf on deep cinnabar red. The Feng Shui Master, a calm white-bearded sage in a slate-grey robe, faces the lens like a trusted teacher and reads the day\'s almanac: a ' + elemEn + ' day under the ' + ruling[0] + '. A slow Ken Burns drift over rising incense smoke; the palette is red and gold, the mood unhurried and certain. This frame sets the tone for the twelve readings that follow.');
out.push('');

ANIMALS.forEach((animal, offset) => {
  const name = animal[0], cn = animal[1];
  const yi = pickB(YI, n, name, 'yi');
  const ji = pickB(JI, n, name, 'ji');
  const direction = pickB(DIRECTIONS, n, name, 'dir');
  const setting = pickB(SETTINGS, n, name, 'setting');
  const note = name === ruling[0]
    ? "Today's ruling sign — its hour is auspicious. "
    : (name === clash[0] ? "Today's clash sign — tread carefully and avoid big moves. " : '');
  out.push('## Scene ' + (offset + 2) + ' — ' + name + ' (' + cn + ')');
  out.push('**Leading character:** ' + name);
  out.push('**Dialog:** "属' + cn + '者，' + yi + '，' + ji + '；' + direction + '方利财"');
  out.push('');
  out.push('Interior/exterior: ' + setting + ', in traditional Chinese ink-wash (国画) style, gold accents on deep red. We find the ' + name + ' zodiac avatar (' + cn + ') — a dignified spirit-creature in red-and-gold silk — composed at the center of the frame. ' + note + 'The day is a ' + elemEn + ' day; the ' + name + ' receives its daily counsel, wealth gathering toward the ' + DIR_EN[direction] + '. A slow contemplative Ken Burns drift; auspicious clouds and a single gold seal settle as the reading lands. The drama is quiet and internal — a daily omen the viewer recognizes for their own sign.');
  out.push('');
});

out.push('## Scene 14 — The Feng Shui Master closes the day');
out.push('**Leading character:** ' + MASTER);
out.push('**Dialog:** "' + pickB(BLESSINGS, n, 'blessing') + '"');
out.push('');
out.push('Exterior of ' + pickB(SETTINGS, n, 'master-outro') + ' at dusk, the same ink-wash (国画) red-and-gold palette. The Feng Shui Master draws the twelve readings back together, lowers both hands in a calm blessing, and a single gold lantern lifts as the incense smoke thins. A slow Ken Burns pull-back until the whole courtyard is in frame — a quiet, certain button on the day.');

const story = out.join('\n').replace(/\s+$/, '') + '\n';
const socialTitle = ('今日运势 Lucky Day — ' + iso).slice(0, 50);
const socialCaption = capBullet.slice(0, 400);
return [{ json: { story, socialTitle, socialCaption, ganzhi: stem + ruling[2], element: elemEn } }];

// Port of storyToDescription() from show/showrunner/story-format.js: drop
// everything before the first '## Scene', collapse each scene's prose to one
// line, append `<Char> says: "<dialog>"`, mapping names through the cast map
// (CAST_ALIASES in show/LuckyDay/show.env). The story markdown comes from the
// deterministic Compute story node (no model in this show), which also
// supplies the social title + caption.
const story = String($json.story || '');
if (!/## Scene/.test(story)) throw new Error('Compute story emitted no "## Scene" blocks — not a story');
const socialTitle = String($json.socialTitle || '').slice(0, 50);
const socialCaption = String($json.socialCaption || '').slice(0, 400);

const ALIASES = {"The Feng Shui Master":"The Feng Shui Master","Rat":"Rat","Ox":"Ox","Tiger":"Tiger","Rabbit":"Rabbit","Dragon":"Dragon","Snake":"Snake","Horse":"Horse","Goat":"Goat","Monkey":"Monkey","Rooster":"Rooster","Dog":"Dog","Pig":"Pig"};
const mapShort = (name) => { for (const k of Object.keys(ALIASES)) if (name.includes(k)) return ALIASES[k]; return String(name).trim(); };

const lines = story.split(/\r?\n/);
let inScene = false, n = 0, prose = '', character = '', dialog = '';
const parts = [];
const emit = () => {
  if (!inScene) return;
  const p = prose.replace(/[ \t]+/g, ' ').trim();
  const s = mapShort(character);
  parts.push(n === 0 ? '- ' + p + ' ' + s + ' says: "' + dialog + '"' : '\n\n  - ' + p + ' ' + s + ' says: "' + dialog + '"');
  n++;
};
for (const line of lines) {
  if (/^## Scene/.test(line)) { emit(); inScene = true; prose = ''; character = ''; dialog = ''; continue; }
  if (!inScene) continue;
  if (/^\*\*Leading character:\*\*/.test(line)) { character = line.replace(/^\*\*Leading character:\*\*[ \t]*/, ''); continue; }
  if (/^\*\*Dialog:\*\*/.test(line)) { dialog = line.replace(/^\*\*Dialog:\*\*[ \t]*/, '').trim().replace(/^"|"$/g, '').replace(/[.。]$/, ''); continue; }
  if (/^##/.test(line)) { emit(); inScene = false; continue; }
  prose += ' ' + line;
}
emit();
if (!parts.length) throw new Error('no scenes parsed from the story');
const plot = parts.join('');
return [{ json: { plot, socialTitle, socialCaption, scenes: n, story } }];

// Shape the engine call: episode mode in the pinned Lucky Day campaign, the
// story as the new episode's plot, optional soundtrack pin. The engine's
// sub-workflow trigger is passthrough — this item IS the payload (same shape
// as the engine webhook's body). Re-delivered same-day stories are diff-aware
// on the engine side, so a duplicate run doesn't re-bill unchanged work.
const cfg = $('Show config').first().json;
if (!cfg.campaignId) throw new Error('Show config: campaignId is empty');
const movie = { plot: $json.plot };
if (cfg.soundtrackAudioPath) {
  movie.soundtrackAudioPath = cfg.soundtrackAudioPath;
  if (cfg.soundtrackVolume) movie.soundtrackVolume = Number(cfg.soundtrackVolume);
}
return [{ json: { target: { mode: 'episode', campaignId: cfg.campaignId }, changes: { movie }, chatWebhookUrl: '' } }];
